module l3vpn-svc {
  namespace "http://example.com/l3vpn-svc";
  prefix l3svc;
  import tailf-ncs { prefix ncs; }
  augment /ncs:services {
    list l3vpn {
      key name;
      uses ncs:service-data;
      ncs:servicepoint "l3vpn-svc";
      leaf name { type string; }
      leaf vrf-name { type string; }
      leaf rt { type string; }
    }
  }
}
